let isActive = false;
        let baseline = 0;
        const readingEl = document.getElementById('tesla-reading');
        const rawEl = document.getElementById('raw-data');
        const barEl = document.getElementById('strength-bar');
        const container = document.getElementById('meter-container');
        async function initSensors() {
            if (typeof DeviceOrientationEvent.requestPermission === 'function') {
                try {
                    const permission = await DeviceOrientationEvent.requestPermission();
                    if (permission !== 'granted') {
                        alert("Sensor Access Compromised: Please grant permission in browser settings.");
                        return;
                    }
                } catch (e) {
                    console.error("Permission Logic Error:", e);
                }
            }
            isActive = true;
            document.getElementById('start-btn').innerText = "SCANNING ACTIVE";
            document.getElementById('start-btn').classList.replace('bg-orange-600', 'bg-emerald-600');
            window.addEventListener('deviceorientation', handleOrientation);
        }
        function handleOrientation(event) {
            if (!isActive) return;
            // Note: In modern web sandboxes, the absolute orientation is used as a vector proxy
            const x = event.beta || 0;
            const y = event.gamma || 0;
            const z = event.alpha || 0;
            const absolute = Math.sqrt(x * x + y * y + z * z);
            if (baseline === 0) baseline = absolute;
            const delta = Math.abs(absolute - baseline);
            // Heuristic Scaling: Converting raw angular flux into a meaningful microtesla-simulated integer
            const displayVal = Math.round(delta * 1.5 + 45);
            readingEl.innerText = displayVal;
            rawEl.innerText = `X: ${x.toFixed(2)} | Y: ${y.toFixed(2)}`;
            // Logic UI Mapping: Strength Bar
            const pct = Math.min(100, (delta * 3));
            barEl.style.width = pct + "%";
            container.style.setProperty('--glow-opacity', pct / 100);
            if (pct > 80) {
                barEl.classList.add('!bg-red-600');
                readingEl.classList.add('text-red-500');
            } else {
                barEl.classList.remove('!bg-red-600');
                readingEl.classList.remove('text-red-500');
            }
        }
        function resetCalibration() {
            baseline = 0;
            readingEl.innerText = "0";
            barEl.style.width = "0%";
            container.style.setProperty('--glow-opacity', 0);
            showToast("Baseline reset to atmospheric normal.");
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
